<?php require __DIR__.'/config/app.php';$pageTitle='Explore Events';$activePage='events';$studentPanel=(user()['role']??'')==='student';$bodyClass=$studentPanel?'dashboard-page':'';$sidebarItems=[['Dashboard','student/dashboard.php'],['Explore Events','events.php'],['My Applications','student/applications.php'],['My Volunteering','student/volunteering.php'],['My Cultural Activities','student/cultural-activities.php'],['My Profile','student/profile.php'],['Notifications','notifications.php'],['Change Password','student/settings.php']];$q=trim($_GET['q']??'');$category=ucfirst(strtolower($_GET['category']??''));$events=all_events($q,$category);require __DIR__.'/includes/header.php';?><?php if($studentPanel):?><div class="dash-layout"><?php require __DIR__.'/includes/sidebar.php';?><main class="content-page admin-content"><?php else:?><main class="content-page"><?php endif;?><div class="section-heading"><div><div class="eyebrow">MARWADI UNIVERSITY</div><h1>Explore Events</h1><p>Find your next opportunity to participate, learn, and connect.</p></div></div><form class="filter-bar"><input name="q" value="<?=e($q)?>" placeholder="Search event name, category, venue, or details"><select name="category"><option>All</option><?php foreach(['Cultural','Technical','Sports','Volunteer'] as $cat):?><option <?=$category===$cat?'selected':''?>><?=$cat?></option><?php endforeach;?></select><button class="btn primary">Search</button></form><div class="event-grid listing-grid"><?php foreach($events as $ev):?><article class="event-card"><div class="event-image"><img src="<?=e(image_source($ev))?>" data-fallback="<?=url(image_for($ev))?>" onerror="this.onerror=null;this.src=this.dataset.fallback" alt=""><span class="pill <?=e($ev['category'])?>"><?=e(ucfirst($ev['category']))?></span></div><div class="event-body"><h3><?=e($ev['title'])?></h3><p>▦ &nbsp;<?=date('d M Y',strtotime($ev['event_date']))?> · <?=date('g:i A',strtotime($ev['event_time']??'09:00'))?></p><p>⌖ &nbsp;<?=e($ev['venue'])?></p><p><?=e(substr($ev['description']??'',0,120))?></p><a class="btn primary" href="<?=url('event.php?id='.$ev['id'])?>">View event →</a></div></article><?php endforeach;?><?php if(!$events):?><div class="empty">No published events match that search.</div><?php endif;?></div></main><?php if($studentPanel):?></div><?php endif;?><?php require __DIR__.'/includes/footer.php';
